public static int sumDivisors(int n) {
    int sum = 0;
    for (int d = 1; d < n; d++) {
        if (n % d == 0) {
            sum = sum + d;
        }
    }
    return sum;
}

public static int countPerfect(int a, int b) {
    int count = 0;
    for (int n = a; n <= b; n++) {
        if (sumDivisors(n) == n) {
            count++;
        }
    }
    return count;
}

